    inv={'schema':'bridge.v2.contour.inventory.v1','source':str(path),'bytes':Path(path).stat().st_size,'sha256':sha(path),'format':'CalculiX ASCII FRD','reader':'PyVista FRDReader','reader_version':pv.__version__,'points':mesh.n_points,'cells':mesh.n_cells,'bounds_mm':list(mesh.bounds),'cell_types':{str(k):int(np.sum(mesh.celltypes==k)) for k in np.unique(mesh.celltypes)},'times':times,'selected_time':selected_time,'selected_frame_index':index,'point_arrays':fields,'cell_arrays':[],'raw_block_inventory':summary,'reader_warnings':[],'blocked_nonselected_arrays':blocked,'required_selected_fields':required,'selected_field_gate':'PASS','full_SDV_visualization':'BLOCKED_UNSUPPORTED_CONTINUATIONS' if blocked else 'NOT_REQUESTED','raw_mesh_identity_and_coverage':'PASS'} # A selected-field pass never certifies unsupported material-history arrays or physical accuracy.
